(function() {
    'use strict';

    class CFOCommandAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'CFO Command';
            this.version = '1.1.0';

            this.OPPS = {
                A: { label: 'Plant Expansion (Peru)', cost: 22, npv: 7.4, irr: 24.3, ebitdaAdd: 4.2, debtReduce: 0 },
                B: { label: 'Acquisition', cost: 38, npv: 11.2, irr: 19.8, ebitdaAdd: 6.8, debtReduce: 0, stressNpv: -4.2 },
                C: { label: 'Debt Paydown', cost: 30, npv: 0, irr: 0, ebitdaAdd: 0, debtReduce: 30 },
                D: { label: 'Share Buyback', cost: 26.4, npv: 0, irr: 0, ebitdaAdd: 0, debtReduce: 0 },
                E: { label: 'R&D Innovation', cost: 15, npv: 4.8, irr: 18.1, ebitdaAdd: 2.1, debtReduce: 0 }
            };

            this.ROUNDS = [
                {
                    panel: 'round1Panel',
                    title: 'Round 1: WACC Calibration',
                    brief: 'Calculate the Weighted Average Cost of Capital for Andina Industrial from first principles. The data below contains three deliberate traps that mirror the most common real-world WACC errors. Choose your inputs carefully — every investment decision in subsequent rounds depends on this number.'
                },
                {
                    panel: 'round2Panel',
                    title: 'Round 2: Investment Evaluation',
                    brief: 'Andina has $40M of investable capital from the asset sale plus access to external financing. Five opportunities compete for funding. Select which to pursue, choose your ranking criterion, and decide whether to incorporate scenario analysis into your decision.'
                },
                {
                    panel: 'round3Panel',
                    title: 'Round 3: Capital Structure Design',
                    brief: ''
                },
                {
                    panel: 'round4Panel',
                    title: 'Round 4: Working Capital Release & Board Presentation',
                    brief: 'Before the board presentation, your finance team has identified $12M of working capital trapped in sub-optimal operations. Select interventions to release cash, and address the disclosure question for any off-balance-sheet arrangements.'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0 || !state.history || state.history.length === 0) {
                state.domainState = {
                    cash: 40,
                    wacc: 0,
                    waccCorrect: 0,
                    creditRating: 'BBB-',
                    selectedOpps: [],
                    totalInvestment: 0,
                    netDebtEbitda: 2.8,
                    interestCoverage: 3.6,
                    wcReleased: 0,
                    disclosed: false,
                    totalScore: 0,
                    scoreHistory: [],
                    roundLabels: [],
                    eventMsg: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    equityBasis: 'book',
                    debtCost: 'coupon',
                    riskAdjust: 'no',
                    selectedOpps: [],
                    rankingMethod: 'irr',
                    scenarioAnalysis: 'base_only',
                    internalCash: 0,
                    newBond: 0,
                    revolver: 0,
                    convertible: 0,
                    equityIssue: 0,
                    wcRecv: false,
                    wcInv: false,
                    wcFact: false,
                    disclosure: false
                };
            }
            this._updateBriefing(state);
            var self = this;
            setTimeout(function() { self._setupListeners(); }, 250);
        }

        validateDecisions(decisions) {
            var st = window.mySimulation.state;
            var round = st.currentPeriod;
            this._updateBriefing(st);

            if (round === 1) {
                var eqEl = document.getElementById('equityBasisSelect');
                var dtEl = document.getElementById('debtCostSelect');
                var raEl = document.getElementById('riskAdjustSelect');
                if (eqEl) decisions.equityBasis = eqEl.value;
                if (dtEl) decisions.debtCost = dtEl.value;
                if (raEl) decisions.riskAdjust = raEl.value;
                return true;
            }

            if (round === 2) {
                var opps = [];
                var ids = ['oppA','oppB','oppC','oppD','oppE'];
                for (var i = 0; i < ids.length; i++) {
                    var el = document.getElementById(ids[i]);
                    if (el && el.checked) opps.push(el.value);
                }
                decisions.selectedOpps = opps;
                var rmEl = document.getElementById('rankingMethodSelect');
                var scEl = document.getElementById('scenarioSelect');
                if (rmEl) decisions.rankingMethod = rmEl.value;
                if (scEl) decisions.scenarioAnalysis = scEl.value;
                if (opps.length === 0) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_no_investment'), 'warning'
                    );
                    return false;
                }
                return true;
            }

            if (round === 3) {
                var ic = document.getElementById('internalCashInput');
                var nb = document.getElementById('newBondInput');
                var rv = document.getElementById('revolverInput');
                var cv = document.getElementById('convertibleInput');
                var eq = document.getElementById('equityInput');
                decisions.internalCash = ic ? parseFloat(ic.value) || 0 : 0;
                decisions.newBond = nb ? parseFloat(nb.value) || 0 : 0;
                decisions.revolver = rv ? parseFloat(rv.value) || 0 : 0;
                decisions.convertible = cv ? parseFloat(cv.value) || 0 : 0;
                decisions.equityIssue = eq ? parseFloat(eq.value) || 0 : 0;

                var totalFin = decisions.internalCash + decisions.newBond + decisions.revolver + decisions.convertible + decisions.equityIssue;
                var needed = st.domainState.totalInvestment;
                if (totalFin < needed) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_financing_short') + ' $' + needed + 'M ' + window.mySimulation.t('warn_needed') + ', $' + totalFin.toFixed(1) + 'M ' + window.mySimulation.t('warn_provided') + '.', 'warning'
                    );
                    return false;
                }
                if (decisions.internalCash > 40) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_cash_limit'), 'warning'
                    );
                    return false;
                }
                return true;
            }

            if (round === 4) {
                var wr = document.getElementById('wcReceivables');
                var wi = document.getElementById('wcInventory');
                var wf = document.getElementById('wcFactoring');
                var dc = document.getElementById('disclosureCheck');
                decisions.wcRecv = wr ? wr.checked : false;
                decisions.wcInv = wi ? wi.checked : false;
                decisions.wcFact = wf ? wf.checked : false;
                decisions.disclosure = dc ? dc.checked : false;
                return true;
            }

            return true;
        }

        calculateResults(state) {
            var round = state.currentPeriod;
            var d = state.decisions;
            var ds = state.domainState;
            var score = 0;
            var roundName = '';
            var feedback = '';

            if (round === 1) {
                roundName = 'WACC Calibration';
                var correct = 0;
                if (d.equityBasis === 'market') correct++;
                if (d.debtCost === 'ytm') correct++;
                if (d.riskAdjust === 'yes') correct++;

                var eqV = d.equityBasis === 'market' ? 220 : 95;
                var dV = 87;
                var tV = eqV + dV;
                var ke = 0.051 + 1.15 * 0.074;
                var kd = d.debtCost === 'ytm' ? 0.078 : 0.092;
                var wacc = (eqV / tV) * ke + (dV / tV) * kd * (1 - 0.35);
                ds.wacc = Math.round(wacc * 1000) / 10;
                ds.waccCorrect = correct;

                if (correct === 3) score = 20;
                else if (correct === 2) score = 13;
                else if (correct === 1) score = 7;
                else score = 0;

                feedback = correct + '/3 errors identified. WACC: ' + ds.wacc + '% (reference: 11.2%)';
                ds.eventMsg = window.mySimulation.t('event_tax_reform');
            }

            if (round === 2) {
                roundName = 'Investment Evaluation';
                var opps = d.selectedOpps || [];
                var totalCost = 0;
                var self = this;
                for (var i = 0; i < opps.length; i++) {
                    var opp = self.OPPS[opps[i]];
                    if (opp) totalCost += opp.cost;
                }
                ds.selectedOpps = opps.slice();
                ds.totalInvestment = totalCost;

                score = 0;
                if (d.rankingMethod === 'npv') score += 10;
                if (d.scenarioAnalysis === 'weighted') score += 8;
                if (opps.indexOf('B') >= 0) score += 4;
                if (totalCost <= 65 && totalCost > 0) score += 3;
                score = Math.min(score, 25);

                feedback = 'Selected: ' + opps.join(', ') + ' | Total: $' + totalCost + 'M | Method: ' + d.rankingMethod.toUpperCase();
                if (opps.indexOf('B') >= 0) {
                    ds.eventMsg = window.mySimulation.t('event_rival_bid');
                } else {
                    ds.eventMsg = '';
                }
            }

            if (round === 3) {
                roundName = 'Capital Structure';
                var newDebt = d.newBond + d.revolver + d.convertible;
                var debtPaydown = 0;
                if (ds.selectedOpps.indexOf('C') >= 0) debtPaydown = 30;

                var pfNetDebt = 87 + newDebt - debtPaydown;
                var pfEBITDA = 31;
                var ndRatio = pfNetDebt / pfEBITDA;

                var curInterest = 7.49;
                if (debtPaydown > 0) curInterest -= 2.76;
                var newInterest = d.newBond * 0.071 + d.revolver * 0.073 + d.convertible * 0.058;
                var totalInterest = curInterest + newInterest;
                var intCov = totalInterest > 0 ? 27 / totalInterest : 99;

                ds.netDebtEbitda = Math.round(ndRatio * 10) / 10;
                ds.interestCoverage = Math.round(intCov * 10) / 10;

                var downgraded = ndRatio > 3.5 || intCov < 3.0;
                ds.creditRating = downgraded ? 'BB+' : 'BBB-';

                score = 0;
                var totalFin = d.internalCash + d.newBond + d.revolver + d.convertible + d.equityIssue;
                if (totalFin >= ds.totalInvestment) score += 3;
                if (!downgraded) score += 12;
                if (newDebt >= 5 && newDebt <= 20) score += 5;
                else if (newDebt > 0 && newDebt < 5) score += 3;
                else if (newDebt > 20 && !downgraded) score += 2;
                if (d.internalCash >= 15) score += 5;
                else if (d.internalCash >= 5) score += 3;
                score = Math.min(score, 25);

                feedback = 'ND/EBITDA: ' + ds.netDebtEbitda + 'x | Coverage: ' + ds.interestCoverage + 'x | Rating: ' + ds.creditRating;
                if (ds.selectedOpps.indexOf('B') >= 0) {
                    ds.eventMsg = window.mySimulation.t('event_cfo_resign');
                } else {
                    ds.eventMsg = '';
                }
            }

            if (round === 4) {
                roundName = 'Working Capital';
                var wcTotal = 0;
                var interventions = 0;
                if (d.wcRecv) { wcTotal += 4.2; interventions++; }
                if (d.wcInv) { wcTotal += 3.8; interventions++; }
                if (d.wcFact) { wcTotal += 4.0; interventions++; }
                ds.wcReleased = Math.round(wcTotal * 10) / 10;
                ds.disclosed = d.disclosure;

                score = 0;
                score += Math.min(Math.round(wcTotal / 12.0 * 15), 15);
                if (d.wcFact && d.disclosure) score += 10;
                else if (!d.wcFact) score += 7;
                if (interventions >= 2) score += 5;
                else if (interventions >= 1) score += 2;
                score = Math.min(score, 30);

                ds.cash = Math.round((40 - Math.min(ds.totalInvestment, 40) + wcTotal) * 10) / 10;
                feedback = 'WC Released: $' + ds.wcReleased + 'M | Interventions: ' + interventions + ' | Disclosed: ' + (d.disclosure ? 'Yes' : 'No');
                ds.eventMsg = '';
            }

            ds.totalScore += score;
            ds.scoreHistory.push(score);
            ds.roundLabels.push(roundName);

            var adapter = this;
            var nextPeriod = round + 1;
            setTimeout(function() {
                if (nextPeriod <= adapter.ROUNDS.length) {
                    adapter._updateBriefing({ currentPeriod: nextPeriod, domainState: ds });
                }
            }, 500);

            return {
                period: state.currentPeriod,
                roundName: roundName,
                score: score,
                totalScore: ds.totalScore,
                feedback: feedback,
                creditRating: ds.creditRating,
                wacc: ds.wacc
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash', (v) => '$' + v + 'M');
            uiManager.bind('ratingDisplay', 'domainState.creditRating');
            uiManager.bind('waccDisplay', 'domainState.wacc', (v) => v > 0 ? v + '%' : '--');
            uiManager.bind('scoreDisplay', 'domainState.totalScore', (v) => v + ' / 100');
        }

        getChartConfig() {
            return {
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Score per Round',
                            data: [],
                            backgroundColor: ['#2c3e50', '#2b6cb0', '#276749', '#b7791f'],
                            borderColor: ['#1a252f', '#1e4e8c', '#1a5632', '#975a16'],
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Score by Round' },
                            legend: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
                                max: 30,
                                title: { display: true, text: 'Points' }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            return {
                scoreChart: {
                    labels: state.domainState.roundLabels,
                    datasets: [{ data: state.domainState.scoreHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var total = 0;
            for (var i = 0; i < history.length; i++) {
                total += (history[i].results ? history[i].results.score || 0 : 0);
            }
            var pct = Math.round(total / 100 * 100);
            var _t = function(k){ try { return window.mySimulation.t(k); } catch(e){ return k; } };
            var performance = _t('perf_insufficient');
            if (pct >= 90) performance = _t('perf_excellent');
            else if (pct >= 70) performance = _t('perf_competent');
            else if (pct >= 50) performance = _t('perf_developing');

            var insights = [];
            if (history.length >= 1 && history[0].results) {
                insights.push(_t(history[0].results.score >= 18 ? 'insight_r1_strong' : 'insight_r1_weak'));
            }
            if (history.length >= 2 && history[1].results) {
                insights.push(_t(history[1].results.score >= 20 ? 'insight_r2_strong' : 'insight_r2_weak'));
            }
            if (history.length >= 3 && history[2].results) {
                insights.push(_t(history[2].results.score >= 18 ? 'insight_r3_strong' : 'insight_r3_weak'));
            }
            if (history.length >= 4 && history[3].results) {
                insights.push(_t(history[3].results.score >= 25 ? 'insight_r4_strong' : 'insight_r4_weak'));
            }

            return {
                totalScore: total,
                maxScore: 100,
                percentage: pct,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            var ds = state.domainState;
            if (ds.eventMsg && ds.eventMsg.length > 0) {
                return ds.eventMsg;
            }
            if (results && results.score !== undefined) {
                var maxForRound = [20, 25, 25, 30];
                var idx = state.currentPeriod - 1;
                if (idx >= 0 && idx < 4 && results.score < maxForRound[idx] * 0.4) {
                    return window.mySimulation.t('hint_review');
                }
            }
            return null;
        }

