            for (var o = 0; o < oppIds.length; o++) {
                var oel = document.getElementById(oppIds[o]);
                if (oel) oel.addEventListener('change', function() { self._updateInvestmentTotal(); });
            }

            var finIds = ['internalCashInput','newBondInput','revolverInput','convertibleInput','equityInput'];
            for (var f = 0; f < finIds.length; f++) {
                var fel = document.getElementById(finIds[f]);
                if (fel) fel.addEventListener('input', function() { self._updateCreditModel(); });
            }

            var wcr = document.getElementById('wcReceivables');
