        _updateWACCPreview() {
            var eqSel = document.getElementById('equityBasisSelect');
            var dtSel = document.getElementById('debtCostSelect');
            if (!eqSel || !dtSel) return;
            var eqV = eqSel.value === 'market' ? 220 : 95;
            var dV = 87;
            var tV = eqV + dV;
            var ke = 0.051 + 1.15 * 0.074;
            var kd = dtSel.value === 'ytm' ? 0.078 : 0.092;
            var wacc = (eqV / tV) * ke + (dV / tV) * kd * (1 - 0.35);
            var el = document.getElementById('waccPreview');
            if (el) el.textContent = (wacc * 100).toFixed(1) + '%';
        }

        _updateInvestmentTotal() {
            var total = 0;
            var ids = ['oppA','oppB','oppC','oppD','oppE'];
            for (var i = 0; i < ids.length; i++) {
                var el = document.getElementById(ids[i]);
                if (el && el.checked && this.OPPS[el.value]) {
                    total += this.OPPS[el.value].cost;
                }
            }
            var disp = document.getElementById('totalInvestment');
            if (disp) disp.textContent = '$' + total + 'M';
        }

        _updateCreditModel() {
            var ds = window.mySimulation ? window.mySimulation.state.domainState : null;
            if (!ds) return;

            var nb = parseFloat((document.getElementById('newBondInput') || {}).value) || 0;
            var rv = parseFloat((document.getElementById('revolverInput') || {}).value) || 0;
            var cv = parseFloat((document.getElementById('convertibleInput') || {}).value) || 0;

            var newDebt = nb + rv + cv;
            var debtPaydown = (ds.selectedOpps && ds.selectedOpps.indexOf('C') >= 0) ? 30 : 0;
            var pfNetDebt = 87 + newDebt - debtPaydown;
            var pfEBITDA = 31;
            var ndRatio = pfNetDebt / pfEBITDA;

            var curInt = 7.49;
            if (debtPaydown > 0) curInt -= 2.76;
            var newInt = nb * 0.071 + rv * 0.073 + cv * 0.058;
            var totalInt = curInt + newInt;
            var intCov = totalInt > 0 ? 27 / totalInt : 99;

            var ndEl = document.getElementById('ndEbitdaDisplay');
            var icEl = document.getElementById('intCoverageDisplay');
            var ndSt = document.getElementById('ndEbitdaStatus');
            var icSt = document.getElementById('intCoverageStatus');
            var pfr = document.getElementById('proFormaRating');

            if (ndEl) ndEl.textContent = ndRatio.toFixed(1) + 'x';
            if (icEl) icEl.textContent = (isFinite(intCov) ? intCov.toFixed(1) : '--') + 'x';

            var ndOk = ndRatio <= 3.5;
            var icOk = isFinite(intCov) && intCov >= 3.0;

            if (ndSt) {
                ndSt.textContent = ndOk ? 'OK' : 'BREACH';
                ndSt.className = ndOk ? 'cfo-sim-status-ok' : 'cfo-sim-status-breach';
            }
            if (icSt) {
                icSt.textContent = icOk ? 'OK' : 'BREACH';
                icSt.className = icOk ? 'cfo-sim-status-ok' : 'cfo-sim-status-breach';
            }
            if (pfr) {
                var ok = ndOk && icOk;
                pfr.textContent = ok ? 'BBB-' : 'BB+ (DOWNGRADE)';
                pfr.style.color = ok ? '#276749' : '#9b2c2c';
            }
        }

        _updateWCTotal() {
            var total = 0;
            var wr = document.getElementById('wcReceivables');
            var wi = document.getElementById('wcInventory');
            var wf = document.getElementById('wcFactoring');
            if (wr && wr.checked) total += 4.2;
            if (wi && wi.checked) total += 3.8;
            if (wf && wf.checked) total += 4.0;
            var el = document.getElementById('wcReleasedDisplay');
            if (el) el.textContent = '$' + total.toFixed(1) + 'M';
        }
    }

